--Проверка, нет ли ошибок в подключении

SELECT
    current_database() AS database_name,
    current_schema() AS schema_name;

-- =============
-- Синхронизация ID
-- =============

/*

Поскольку мы вставляли customer_id, category_id и другие ID вручную, после заполнения таблиц синхронизируем счётчики identity. Это нужно, чтобы будущие INSERT без указания ID не столкнулись с уже существующими значениями.
*/


SELECT setval(
    pg_get_serial_sequence('customers', 'customer_id'),
    (SELECT MAX(customer_id) FROM customers),
    true
);

SELECT setval(
    pg_get_serial_sequence('categories', 'category_id'),
    (SELECT MAX(category_id) FROM categories),
    true
);

SELECT setval(
    pg_get_serial_sequence('products', 'product_id'),
    (SELECT MAX(product_id) FROM products),
    true
);

SELECT setval(
    pg_get_serial_sequence('orders', 'order_id'),
    (SELECT MAX(order_id) FROM orders),
    true
);

SELECT setval(
    pg_get_serial_sequence('payments', 'payment_id'),
    (SELECT MAX(payment_id) FROM payments),
    true
);

-- =========
-- Проверяем, что данные загрузились
-- =========

SELECT 'customers' AS table_name, COUNT(*) AS rows_count
FROM customers

UNION ALL

SELECT 'categories', COUNT(*)
FROM categories

UNION ALL

SELECT 'products', COUNT(*)
FROM products

UNION ALL

SELECT 'orders', COUNT(*)
FROM orders

UNION ALL

SELECT 'payments', COUNT(*)
FROM payments;










SELECT COUNT(*) AS total_customers
FROM customers;



SELECT
    COUNT(*) AS total_orders,
    COUNT(DISTINCT customer_id) AS unique_customers
FROM orders;



SELECT
    COUNT(*) AS payments_count,
    SUM(amount) AS total_amount,
    ROUND(AVG(amount), 2) AS avg_amount
FROM payments;



SELECT
    MIN(price) AS min_price,
    MAX(price) AS max_price,
    ROUND(AVG(price), 2) AS avg_price,
    COUNT(*) AS products_count
FROM products;



SELECT
    COUNT(*) AS paid_count,
    SUM(amount) AS paid_total,
    ROUND(AVG(amount), 2) AS paid_avg,
    MAX(amount) AS paid_max
FROM payments
WHERE payment_status = 'Paid';



SELECT
    COUNT(*) AS items_count,
    SUM(quantity) AS total_units,
    ROUND(AVG(quantity), 2) AS avg_units,
    MAX(quantity) AS max_units
FROM order_items;



SELECT
    SUM(quantity * unit_price) AS total_revenue,
    ROUND(AVG(quantity * unit_price), 2) AS avg_item_cost,
    MIN(quantity * unit_price) AS min_item_cost,
    MAX(quantity * unit_price) AS max_item_cost
FROM order_items;



SELECT
    COUNT(*) AS orders_count,
    ROUND(AVG(quantity), 2) AS avg_quantity,
    MIN(quantity) AS min_quantity,
    MAX(quantity) AS max_quantity
FROM orders
WHERE order_date BETWEEN '2025-01-01' AND '2025-12-31';




--assignment
--aktivnost klientov
SELECT
    c.customer_name,
    COUNT(*) AS orders_count
FROM customers AS c
INNER JOIN orders AS o
    ON o.customer_id = c.customer_id
GROUP BY c.customer_id, c.customer_name
HAVING COUNT(*) > 2;


--zavershennye zakazy klientov
SELECT
    c.customer_name,
    c.city,
    COUNT(*) AS completed_orders_count
FROM customers AS c
INNER JOIN orders AS o
    ON o.customer_id = c.customer_id
WHERE LOWER(o.status::text) = 'completed'
GROUP BY c.customer_id, c.customer_name, c.city
HAVING COUNT(*) > 1;


--analiz sposobov oplaty
SELECT
    payment_method,
    COUNT(*) AS payments_count,
    SUM(amount) AS total_amount,
    ROUND(AVG(amount), 2) AS avg_amount
FROM payments
GROUP BY payment_method
HAVING COUNT(*) > 3;


--analiz kategoriy tovarov
SELECT
    c.category_name,
    SUM(oi.quantity) AS total_units,
    SUM(oi.quantity * oi.unit_price) AS total_revenue
FROM categories AS c
INNER JOIN products AS p
    ON p.category_id = c.category_id
INNER JOIN order_items AS oi
    ON oi.product_id = p.product_id
GROUP BY c.category_id, c.category_name
HAVING SUM(oi.quantity) > 5;


--analiz skidok
SELECT
    status,
    ROUND(AVG(discount::numeric), 2) AS avg_discount,
    MAX(discount) AS max_discount,
    COUNT(*)AS orders_count
FROM orders
GROUP BY status
HAVING AVG(discount::numeric) > 10;


--analiz klientskoy bazy po gorodam
SELECT
    city,
    COUNT(DISTINCT customer_id) AS unique_customers
FROM customers
GROUP BY city
HAVING COUNT(DISTINCT customer_id) > 2;


--analiz viruchki po klientam
SELECT
    c.customer_name,
    COUNT(DISTINCT o.order_id) AS completed_orders_count,
    SUM(oi.quantity * oi.unit_price) AS total_revenue
FROM customers AS c
INNER JOIN orders AS o
    ON o.customer_id = c.customer_id
INNER JOIN order_items AS oi
    ON oi.order_id = o.order_id
WHERE LOWER(o.status::text) = 'completed'
GROUP BY c.customer_id, c.customer_name
HAVING COUNT(DISTINCT o.order_id) > 1
   AND SUM(oi.quantity * oi.unit_price) > 10000
ORDER BY total_revenue DESC;







--drugoi assignment
--analyz tovarov po cenovim categoriyam
WITH classified AS (
    SELECT CASE
        WHEN price < 2000 THEN 'Low'
        WHEN price <= 5000 THEN 'Medium'
        WHEN price > 5000 THEN 'High'
    END AS price_category
    FROM products
)
SELECT price_category, COUNT(*) AS product_count
FROM classified
WHERE price_category IS NOT NULL
GROUP BY price_category;


--analiz zakazov po skidkam
WITH classified AS (
    SELECT discount,
           CASE
               WHEN discount = 0 THEN 'No discount'
               WHEN discount BETWEEN 0.01 AND 10 THEN 'Low discount'
               WHEN discount > 10 THEN 'High discount'
           END AS discount_category
    FROM orders
)
SELECT discount_category,
       COUNT(*) AS order_count,
       ROUND(AVG(discount), 2) AS average_discount,
       MAX(discount) AS max_discount
FROM classified
WHERE discount_category IS NOT NULL
GROUP BY discount_category;


--analiz statusov zakazov
WITH classified AS (
    SELECT discount,
           CASE
               WHEN status IN ('completed', 'shipped') THEN 'Successful'
               WHEN status = 'processing' THEN 'In Progress'
               WHEN status = 'cancelled' THEN 'Cancelled'
           END AS order_group
    FROM orders
)
SELECT order_group,
       COUNT(*) AS order_count,
       ROUND(AVG(discount), 2) AS average_discount
FROM classified
WHERE order_group IS NOT NULL
GROUP BY order_group;


--analiz tovarov po cenovim segmentam
WITH classified AS (
    SELECT price,
           CASE
               WHEN price < 1500 THEN 'Budget'
               WHEN price <= 7000 THEN 'Standard'
               WHEN price > 7000 THEN 'Premium'
           END AS price_segment
    FROM products
)
SELECT price_segment,
       COUNT(*) AS product_count,
       ROUND(AVG(price), 2) AS average_price,
       MIN(price) AS min_price,
       MAX(price) AS max_price
FROM classified
WHERE price_segment IS NOT NULL
GROUP BY price_segment
ORDER BY MIN(price);


--analiz viruchki po cenovim categoriyam
WITH sales AS (
    SELECT oi.quantity,
           oi.unit_price,
           CASE
               WHEN p.price < 2000 THEN 'Budget'
               WHEN p.price <= 6000 THEN 'Medium'
               WHEN p.price > 6000 THEN 'Premium'
           END AS price_category
    FROM products AS p
    INNER JOIN order_items AS oi ON oi.product_id = p.product_id
)
SELECT price_category,
       SUM(quantity) AS units_sold,
       SUM(quantity * unit_price) AS total_revenue,
       ROUND(AVG(unit_price), 2) AS average_sale_price
FROM sales
WHERE price_category IS NOT NULL
GROUP BY price_category;

--sravnenie zakazov po skidkam i statusam
WITH classified AS (
    SELECT status,
           discount,
           CASE
               WHEN discount = 0 THEN 'No discount'
               WHEN discount > 0 THEN 'With discount'
           END AS discount_category
    FROM orders
)
SELECT discount_category,
       status,
       COUNT(*) AS order_count,
       ROUND(AVG(discount), 2) AS average_discount
FROM classified
WHERE discount_category IS NOT NULL
GROUP BY discount_category, status;


--kompleksnii analiz prodazh po categoriyam tovarov
WITH sales AS (
    SELECT c.category_name AS product_category,
           oi.quantity,
           oi.unit_price,
           CASE
               WHEN p.price < 2000 THEN 'Budget'
               WHEN p.price <= 7000 THEN 'Standard'
               WHEN p.price > 7000 THEN 'Premium'
           END AS price_segment
    FROM products AS p
    INNER JOIN order_items AS oi ON oi.product_id = p.product_id
    INNER JOIN categories AS c ON c.category_id = p.category_id
)
SELECT product_category,
       price_segment,
       SUM(quantity) AS units_sold,
       SUM(quantity * unit_price) AS total_revenue,
       ROUND(AVG(unit_price), 2) AS average_sale_price
FROM sales
WHERE price_segment IS NOT NULL
GROUP BY product_category, price_segment
ORDER BY total_revenue DESC;